from flask import Blueprint, request, jsonify, make_response, redirect, session
import hashlib
import time
import uuid
import secrets
from datetime import datetime, timedelta

from chain import append_witness_event
from vault_store import vault_store

bp = Blueprint('maddie_v4', __name__, url_prefix='/v1')

# In-memory stores (production: replace with persistent DB)
_invites = {}
_sessions = {}
_claims = {}
_audit_log = []
_beneficiaries = {}
_stories = {}
_estate_state = {}  # subject_id -> state string


# ─── HELPERS ───

def _actor():
    return session.get('actor_id', request.headers.get('X-Actor-Id', 'anonymous'))


def _require_scope(*allowed):
    scope = session.get('scope', request.headers.get('X-Scope', ''))
    if scope not in allowed:
        return jsonify(error='forbidden', required_scopes=list(allowed)), 403
    return None


def _audit(subject_id, action, evidence_hash=None, extra=None):
    entry = {
        'timestamp': datetime.utcnow().isoformat() + 'Z',
        'actor_id': _actor(),
        'action': action,
        'subject_id': subject_id,
        'evidence_hash': evidence_hash,
        'witness_attestation_id': str(uuid.uuid4()),
    }
    if extra:
        entry.update(extra)
    _audit_log.append(entry)
    append_witness_event({
        'event': 'estate_audit',
        'detail': entry,
    })
    return entry


# ─── AUTH: MAGIC-LINK (auth-friction-001) ───
# HARD RULE: No password, no email input, no username, no token-paste field.
# Auth is magic-link only. Server binds token on click.

@bp.route('/invite', methods=['POST'])
def create_invite():
    err = _require_scope('FAMILY_ADMIN')
    if err:
        return err
    data = request.get_json(force=True)
    subject_name = data.get('subject_name')
    delivery = data.get('delivery')  # "sms" or "email"
    contact = data.get('contact')
    if not subject_name or delivery not in ('sms', 'email') or not contact:
        return jsonify(error='subject_name, delivery (sms|email), and contact required'), 400

    invite_token = secrets.token_urlsafe(32)
    invite_id = str(uuid.uuid4())
    _invites[invite_token] = {
        'invite_id': invite_id,
        'subject_name': subject_name,
        'delivery': delivery,
        'contact': contact,
        'status': 'INVITE_SENT',
        'created_at': datetime.utcnow().isoformat() + 'Z',
    }
    append_witness_event({'event': 'invite_created', 'invite_id': invite_id, 'delivery': delivery})
    # In production: dispatch SMS/email with link /v1/auth/magic/{invite_token}
    return jsonify(invite_id=invite_id, status='INVITE_SENT', magic_link=f'/v1/auth/magic/{invite_token}'), 201


@bp.route('/auth/magic/<invite_token>', methods=['GET'])
def magic_link_click(invite_token):
    """Public endpoint. Clicking the magic link binds a SUBJECT_TOKEN server-side."""
    inv = _invites.get(invite_token)
    if not inv:
        return jsonify(error='invalid or expired invite'), 404

    subject_token = secrets.token_urlsafe(48)
    subject_id = str(uuid.uuid4())
    _sessions[subject_token] = {
        'subject_id': subject_id,
        'subject_name': inv['subject_name'],
        'invite_id': inv['invite_id'],
        'scope': 'SUBJECT',
        'created_at': time.time(),
    }
    inv['status'] = 'LINK_CLICKED'

    append_witness_event({
        'event': 'magic_link_activated',
        'invite_id': inv['invite_id'],
        'subject_id': subject_id,
    })

    resp = make_response(redirect('/v1/ui/main'))
    resp.set_cookie(
        'SUBJECT_TOKEN', subject_token,
        httponly=True, secure=True, samesite='Strict',
        max_age=86400,
    )
    return resp


@bp.route('/auth/session', methods=['GET'])
def session_info():
    token = request.cookies.get('SUBJECT_TOKEN')
    sess = _sessions.get(token)
    if not sess:
        return jsonify(authenticated=False), 401
    return jsonify(authenticated=True, subject_name=sess['subject_name'], subject_id=sess['subject_id'])


@bp.route('/auth/logout', methods=['POST'])
def logout():
    token = request.cookies.get('SUBJECT_TOKEN')
    _sessions.pop(token, None)
    resp = make_response(jsonify(ok=True))
    resp.delete_cookie('SUBJECT_TOKEN')
    append_witness_event({'event': 'logout', 'actor': _actor()})
    return resp


